"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["48492"],{39722(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.grupo_peso_area_enem_congelado.sem_areas","status":422,"titulo":"Cada grupo do quadro de pesos por \xe1rea precisa de ao menos uma \xe1rea"},"descricao":{"codigo":"uniplus.selecao.grupo_peso_area_enem_congelado.sem_areas","requisitos":[],"oQueAconteceu":["O grupo do quadro de pesos por \xe1rea n\xe3o traz nenhuma \xe1rea. Sem \xe1rea n\xe3o h\xe1 peso nem m\xe9dia\\nponderada para o grupo, e a nota da etapa do ENEM n\xe3o teria resultado.","Esta confer\xeancia vem depois das de cada \xe1rea e substitui a da soma dos pesos\\n([`pesos_somam_zero`](/erros/uniplus.selecao.grupo_peso_area_enem_congelado.pesos_somam_zero)), que s\xf3 vale para o grupo que tem \xe1reas.","Na classifica\xe7\xe3o baseada em ENEM com c\xe1lculo local pela m\xe9dia ponderada, o processo declara uma\\nresolu\xe7\xe3o de Pesos por \xc1rea e copia, do cadastro de Pesos por \xc1rea (Configura\xe7\xe3o), o quadro de\\npesos de cada grupo de \xe1rea do ENEM: o grupo, a base legal da linha e, para cada \xe1rea, o peso e o\\ncorte (a nota m\xednima da \xe1rea, que pode n\xe3o existir). A c\xf3pia \xe9 congelada com o processo; editar o\\ncadastro depois n\xe3o a altera, e quem quiser os valores novos redefine a classifica\xe7\xe3o.","O cadastro de Pesos por \xc1rea j\xe1 confere esses valores ao gravar a linha, e a defini\xe7\xe3o da\\nclassifica\xe7\xe3o os confere de novo ao copi\xe1-los. A recusa vem no campo `resolucaoPesoAreaEnem` e\\nacumula, na mesma resposta, com as demais viola\xe7\xf5es da classifica\xe7\xe3o e dos outros grupos do\\nquadro.","Este mesmo c\xf3digo tamb\xe9m aparece quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o publicada:\\nem toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios, as opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa\\nest\xe1 no cabe\xe7alho da p\xe1gina). Antes disso, o sistema confere a integridade dos bytes congelados:\\nbytes alterados depois do congelamento s\xe3o recusados por [`integridade_violada`](/erros/uniplus.selecao.envelope_codec.integridade_violada) e n\xe3o chegam a esta\\ncausa. Pelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz esse defeito, porque a\\ndefini\xe7\xe3o o recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o \xfanica, sem a lista\\n`errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Corrija a linha de Pesos por \xc1rea da resolu\xe7\xe3o declarada, no cadastro de Configura\xe7\xe3o, com ao menos uma \xe1rea, com peso, no grupo, e\\nenvie a defini\xe7\xe3o da classifica\xe7\xe3o de novo. Se a resposta trouxer mais de uma viola\xe7\xe3o em\\n`errors[]`, corrija todas antes de reenviar. O cadastro j\xe1 recusa esse defeito ao gravar a linha: se ele chegou\\nat\xe9 aqui, a linha foi gravada por caminho que n\xe3o passou por essa confer\xeancia, e a causa \xe9\\ninvestigada pela equipe t\xe9cnica do Uni+.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no\\ncabe\xe7alho, exceto a defini\xe7\xe3o da classifica\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Grupo peso area enem congelado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);